import { Order } from './types';

interface CursorPair { createdAt: string; id: string }

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  list(tenant: string): Order[] {
    return this.sorted(this.matching(tenant));
  }
  page(tenant: string, limit: number, cursor?: CursorPair): { items: Order[]; nextCursor: string | null } {
    // Filtering precedes pagination, so a cursor pair from another tenant or a
    // since-deleted row cannot skip or repeat any of this tenant's orders.
    const sorted = this.sorted(this.matching(tenant));
    let start = 0;
    if (cursor) {
      // Resume strictly after the cursor pair; never at or before it.
      start = sorted.findIndex(row => this.compare(row, cursor) > 0);
      if (start === -1) start = sorted.length;
    }
    const items = sorted.slice(start, start + limit);
    const last = items.length > 0 ? items[items.length - 1] : undefined;
    const hasMore = last !== undefined && sorted.some(row => this.compare(row, last) > 0);
    return { items, nextCursor: hasMore ? `${last.createdAt}|${last.id}` : null };
  }
  private matching(tenant: string): Order[] {
    // filter returns a new array, so this.rows is never mutated.
    return this.rows.filter(row => row.tenant === tenant);
  }
  private sorted(rows: Order[]): Order[] {
    return rows.sort((a, b) => this.compare(a, b));
  }
  private compare(a: CursorPair, b: CursorPair): number {
    if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
    if (a.id !== b.id) return a.id < b.id ? -1 : 1;
    return 0;
  }
}
