const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const rows = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'c', tenant: 'a', createdAt: '2026-01-01', total: 4 },
  { id: 'd', tenant: 'a', createdAt: '2026-01-02', total: 5 }
];
const handler = new OrderHandler(new OrderRepository(rows));

// Sorted ascending by createdAt then id, tenant filter kept.
const p1 = handler.list({ tenant: 'a', limit: 10 });
assert.deepEqual(p1.items.map(x => x.id), ['a', 'c', 'b', 'd']);
assert.equal(p1.nextCursor, null);

// Page one at a time via nextCursor; no repeats, no skips.
let seen = [];
let cursor;
for (let i = 0; i < 10; i++) {
  const p = handler.list({ tenant: 'a', limit: 1, cursor });
  if (p.items.length === 0) { assert.equal(p.nextCursor, null); break; }
  seen.push(p.items[0].id);
  if (seen.length < 4) assert.notEqual(p.nextCursor, null);
  cursor = p.nextCursor;
}
assert.deepEqual(seen, ['a', 'c', 'b', 'd']);

// Cursor resumes strictly after the pair even if that row was deleted.
const sparse = new OrderHandler(new OrderRepository(rows.filter(r => r.id !== 'c')));
const p2 = sparse.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|c' });
assert.deepEqual(p2.items.map(x => x.id), ['b', 'd']);

// Cursor pair belonging to another tenant must not skip this tenant's rows.
const p3 = handler.list({ tenant: 'a', limit: 10, cursor: '2026-01-01|x' });
assert.deepEqual(p3.items.map(x => x.id), ['a', 'c', 'b', 'd']);

// Filtering precedes pagination with an early foreign cursor.
const p4 = handler.list({ tenant: 'b', limit: 10, cursor: '2020-01-01|z' });
assert.deepEqual(p4.items.map(x => x.id), ['x']);
const p5 = handler.list({ tenant: 'b', limit: 10, cursor: '2026-01-01|x' });
assert.deepEqual(p5.items, []);
assert.equal(p5.nextCursor, null);

// Cursor before everything starts at the first row.
const p6 = handler.list({ tenant: 'a', limit: 2, cursor: '2020-01-01|a' });
assert.deepEqual(p6.items.map(x => x.id), ['a', 'c']);
assert.equal(p6.nextCursor, '2026-01-01|c');

// Repository input is not mutated.
assert.deepEqual(rows.map(r => r.id), ['b', 'x', 'a', 'c', 'd']);

// Invalid requests.
for (const bad of [
  { tenant: '', limit: 1 },
  { tenant: 'a', limit: 0 },
  { tenant: 'a', limit: 101 },
  { tenant: 'a', limit: 1.5 },
  { tenant: 'a', limit: 1, cursor: '' },
  { tenant: 'a', limit: 1, cursor: '2026-01-01' },
  { tenant: 'a', limit: 1, cursor: '2026-01-01|' },
  { tenant: 'a', limit: 1, cursor: '|c' },
  { tenant: 'a', limit: 1, cursor: '2026-01-01|c|extra' }
]) {
  assert.throws(() => handler.list(bad), /invalid request/, JSON.stringify(bad));
}

console.log('checks/cursor.cjs passed');
EOF
